%[text] 发现2:Transfer 过程是layer 2为模版的，L2编码了早期的记忆，晚期的动作目的，并在迁移过程中共用了L2，而L5参与了行为
%[text:tableOfContents]{"heading":"目录"}
%[text] # 新群体A
%[text] 学习早期
%[text] 功能：记录刺激
%[text] 1. 时间提前
%[text] 2. 活动低
%[text] 3. 对cue不响应 \
%[text] L5无时间提前
%[text] L2早于L5
MOpBaseline=TransferLearning.MOpBaseline;
QueryTablePath=TransferLearning.ProjectPath('查询表.xlsx');
%%
EnsembleA=UniExp.NtatsCellStrip(MOpBaseline.QueryNTATS(UniExp.ReadQueryTable(QueryTablePath,'Fig2A'),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median)); %[output:74dd5504]
Brain="MOp";
Phases=["AudioOnly","AudioWater_First","AudioWater_Last"];
SubTitles=["🔊","🔊💧Trial 1~15","🔊💧Trial 16~20"];
[~,Index]=ismember(EnsembleA.CellUID,MOpBaseline.Cells.CellUID);
EnsembleA.ZLayer=MOpBaseline.Cells.ZLayer(Index);
Logical=EnsembleA.ZLayer=="MOp5";
Cells5=sum(Logical);
Cells23=sum(~Logical);
[PeakValue,EnsembleA.PeakTime]=max(EnsembleA.NTATS,[],2);
EnsembleA=EnsembleA(PeakValue.AudioWater_First>PeakValue.AudioOnly&PeakValue.AudioWater_Last>PeakValue.AudioOnly&EnsembleA.PeakTime.AudioWater_First>24&EnsembleA.PeakTime.AudioWater_Last>24,:);
EnsembleA.PeakTime=EnsembleA.PeakTime.AudioWater_Last;
EnsembleA=sortrows(EnsembleA,'PeakTime');
Logical=EnsembleA.ZLayer=="MOp5";
Layer2=EnsembleA.NTATS{~Logical,:,Phases};
MajorCells23=height(Layer2);
Layer5=EnsembleA.NTATS{Logical,:,Phases};
MajorCells5=height(Layer5);
[MeanLine,SemLine]=MATLAB.DataFun.MeanSem(Layer2,1);
[MeanLine(2,:,:),SemLine(2,:,:)] = MATLAB.DataFun.MeanSem(Layer5,1);
MeanLine=pagetranspose(MeanLine);
SemLine=pagetranspose(SemLine);
NumPhases=numel(Phases);
Xs=linspace(seconds(-3),seconds(3),width(Layer2)).';
%%
Fig=figure; %[output:6e966506]
Layout=tiledlayout(3,NumPhases,TileSpacing='tight',Padding='tight'); %[output:6e966506]
Axes=gobjects(3,NumPhases);
for P=1:NumPhases
	Axes(1,P)=nexttile(P); %[output:6e966506]
	imagesc(seconds([-3,3]),[1,height(Layer2)],Layer2(:,:,P));
	xline(seconds(0),':k');
	xline(seconds(1),'-k');
	title(SubTitles(P));
	Axes(1,P).XAxis.Visible=false;
	Axes(2,P)=nexttile(P+NumPhases);
	imagesc(seconds([-3,3]),[1,height(Layer5)],Layer5(:,:,P));
	xline(seconds(0),':k');
	xline(seconds(1),'-k');
	Axes(2,P).XAxis.Visible=false;
	Axes(3,P)=nexttile(P+NumPhases+NumPhases);
	Lines=MATLAB.Graphics.MultiShadowedLines(MeanLine(:,:,P),SemLine(:,:,P),1/3,EdgeColors=[1,0,0;0,0,1],X=Xs);
	xline(seconds(0),':k');
	xline(seconds(1),'-k');
	if P==1
		LegendLines=Lines;
	end
end
for P=2:NumPhases
	Axes(1,P).YAxis.Visible=false; %[output:6e966506]
	Axes(2,P).YAxis.Visible=false;
	Axes(3,P).YAxis.Visible=false;
end
for P=1:2
	box(Axes(P,1),'off'); %[output:6e966506]
	yticks(Axes(P,1),[]);
end
ylabel(Axes(1,1),sprintf('%s2/3\n%u/%u\n%s%% cells',Brain,MajorCells23,Cells23,MATLAB.SignificantFixedpoint(MajorCells23/Cells23*100,2))); %[output:6e966506]
ylabel(Axes(2,1),sprintf('%s5\n%u/%u\n%s%% cells',Brain,MajorCells5,Cells5,MATLAB.SignificantFixedpoint(MajorCells5/Cells5*100,2))); %[output:6e966506]
ylabel(Axes(3,1),'z-score ±SEM'); %[output:6e966506]
xlabel(Layout,'Time from cue(:) water(|)'); %[output:6e966506]
CLim=MATLAB.Graphics.UnifyAxesLims(Axes(1:2,:),@clim); %[output:6e966506]
MATLAB.Graphics.UnifyAxesLims(Axes(3,:),@ylim); %[output:6e966506]
[MinColor,MaxColor]=bounds(CLim);
LowColors=MATLAB.ElMat.LinSpace([0,0,1],[1,1,1],255);
colormap(Fig,[LowColors(uint8((1+MinColor/MaxColor)*255)+1:end,:);MATLAB.ElMat.LinSpace([1,1,1],[1,0,0],255).^2]); %[output:6e966506]
CB=colorbar(Axes(2,NumPhases));  %[output:6e966506]
CB.Label.String='z-score'; %[output:6e966506]
legend(LegendLines,Brain+["2/3","5"],Location=MATLAB.Graphics.OptimizedLegendLocation(LegendLines)); %[output:6e966506]
MATLAB.Graphics.FigureAspectRatio(8,5,MATLAB.Flags.Narrow); %[output:6e966506]
print(Fig,TransferLearning.ProjectPath('Fig2A热线图.svg'),'-dsvg'); %[output:6e966506]

